<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sayfalar</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:13px;border-bottom:1px solid #edf0ed}.btn{background:#176b50;color:white;padding:10px 14px;border-radius:8px;text-decoration:none}</style></head><body><main class="wrap"><h1>İçerik sayfaları</h1><p><a class="btn" href="/admin/pages/new">Yeni sayfa</a></p><section class="panel"><table><thead><tr><th>Başlık</th><th>URL</th><th>Durum</th><th></th></tr></thead><tbody><?php foreach($pages as $page): ?><tr><td><?= e($page['title']) ?></td><td>/page/<?= e($page['slug']) ?></td><td><?= e($page['status']) ?></td><td><a href="/admin/pages/<?= (int)$page['id'] ?>">Düzenle</a></td></tr><?php endforeach; ?><?php if(!$pages): ?><tr><td colspan="4">Henüz sayfa oluşturulmamış.</td></tr><?php endif; ?></tbody></table></section><p><a href="/admin">Yönetim paneli</a></p></main></body></html>